import{_ as t,o as e,c as a,ah as i}from"./chunks/framework.BVKoBI-M.js";const s="/projects/AiNovaRobot/en/latest/assets/image1.Ds8uPVG6.webp",r="/projects/AiNovaRobot/en/latest/assets/image2.BP29WQlN.webp",n="/projects/AiNovaRobot/en/latest/assets/image3.B_FrbYhz.webp",l="/projects/AiNovaRobot/en/latest/assets/image4.5c9TXTnI.webp",g="/projects/AiNovaRobot/en/latest/assets/image5.BGzbh0ar.webp",c="data:image/png;base64,",A="/projects/AiNovaRobot/en/latest/assets/image7.BkIObGLO.webp",d="data:image/jpeg;base64,",m="/projects/AiNovaRobot/en/latest/assets/image1.153Xmbmi.webp",h="/projects/AiNovaRobot/en/latest/assets/image2.Bl5Q_ppM.webp",p="/projects/AiNovaRobot/en/latest/assets/image3.DvtMal8f.webp",w="/projects/AiNovaRobot/en/latest/assets/image4.DEGgzcNw.webp",f="/projects/AiNovaRobot/en/latest/assets/image5.Cr6RMIlh.webp",b="/projects/AiNovaRobot/en/latest/assets/image6.srInxupS.webp",u="/projects/AiNovaRobot/en/latest/assets/image7.CpxrToJi.webp",D="/projects/AiNovaRobot/en/latest/assets/image8.D_-6gGXU.webp",Q="/projects/AiNovaRobot/en/latest/assets/image9.DAl2plIA.webp",N="/projects/AiNovaRobot/en/latest/assets/image10.-S-x_Xk5.webp",y="/projects/AiNovaRobot/en/latest/assets/image11.nnlVouhP.webp",B="/projects/AiNovaRobot/en/latest/assets/image12.DRtfRdWg.webp",R="/projects/AiNovaRobot/en/latest/assets/image13.DrMHpPnW.webp",v="/projects/AiNovaRobot/en/latest/assets/image14.DiMtqoOo.webp",P="/projects/AiNovaRobot/en/latest/assets/image15.CVWYz-VU.webp",x="/projects/AiNovaRobot/en/latest/assets/image16.DKJCtccC.webp",U="/projects/AiNovaRobot/en/latest/assets/image17.BNPiir1-.webp",W=JSON.parse('{"title":"3. Program Download","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Program_Download.md","filePath":"docs/3.Program_Download.md"}'),E={name:"docs/3.Program_Download.md"};function C(q,o,_,G,j,O){return e(),a("div",null,[...o[0]||(o[0]=[i('<h1 id="_3-program-download" tabindex="-1">3. Program Download <a class="header-anchor" href="#_3-program-download" aria-label="Permalink to &quot;3. Program Download&quot;">​</a></h1><h2 id="_3-1-program-download" tabindex="-1">3.1 Program Download <a class="header-anchor" href="#_3-1-program-download" aria-label="Permalink to &quot;3.1 Program Download&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This lesson will demonstrate how to download program to AiNova. The game program has been placed in Appendix under the same directory. You can copy the programs to your computer in advance to facilitate the following operations.</strong></p></div><h3 id="_3-1-1-getting-ready" tabindex="-1">3.1.1 Getting Ready <a class="header-anchor" href="#_3-1-1-getting-ready" aria-label="Permalink to &quot;3.1.1 Getting Ready&quot;">​</a></h3><ul><li><strong>Software Installation</strong></li></ul><p>Please view WonderCode installation method in folder “<strong>1.Getting Ready/Lesson 3 Software Program</strong>” to install WonderCode and learn about the function of software interface.</p><img loading="lazy" height="509" width="716" src="'+s+'" style="width:800px;" class="common_img"><ul><li><strong>Hardware Preparation</strong></li></ul><p>According to “<strong>Lesson 1 Mini AI Autonomous Driving Kit Introduction</strong>”, after assembling this kit, prepare AiNova (flat view), traffic light controller and USB cable, as the figure shown below:</p><h3 id="_3-1-2-load-program" tabindex="-1">3.1.2 Load Program <a class="header-anchor" href="#_3-1-2-load-program" aria-label="Permalink to &quot;3.1.2 Load Program&quot;">​</a></h3><ol><li>Open WonderCode.</li></ol><img loading="lazy" height="107" width="98" src="'+r+'" style="width:200px;" class="common_img"><ol start="2"><li>Click “<strong>File</strong>”, and then click “<strong>Load file from your computer</strong>”, as the figure shown below:</li></ol><img loading="lazy" height="188" width="370" src="'+n+'" style="width:500px;" class="common_img"><ol start="3"><li>Then choose “<strong>Mini AI Autonomous Driving Program</strong>” and click “<strong>Open</strong>” to load game program in software interface or directly drag the program to software interface.</li></ol><img loading="lazy" height="134" width="770" src="'+l+'" style="width:800px;" class="common_img"><h3 id="_3-1-3-program-download" tabindex="-1">3.1.3 Program Download <a class="header-anchor" href="#_3-1-3-program-download" aria-label="Permalink to &quot;3.1.3 Program Download&quot;">​</a></h3><ol><li><p>Connect AiNova robot to your computer with USB cable.</p></li><li><p>Click “<strong>Connect device</strong>” in home interface and select corresponding port. (The port number is selected based on actual situation. The following example port is COM9. )</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If COM1 appears, please do not select. COM1 is a system communication port.</strong></p></div><img loading="lazy" height="102" width="177" src="'+g+'" style="width:200px;" class="inline-icon"><img loading="lazy" height="65" width="190" src="'+c+'" style="width:200px;" class="common_img"><ol start="3"><li>After connecting, Click “<strong>Upload</strong>” in upload mode.</li></ol><img loading="lazy" height="110" width="485" src="'+A+'" style="width:500px;" class="common_img"><ol start="4"><li>Wait until the download is completed.</li></ol><img loading="lazy" height="49" width="141" src="'+d+'" style="width:200px;" class="common_img"><ol start="5"><li>Traffic light program is downloaded according to the same method. You just need to replace the program in “<strong>2.Load Program</strong>”</li></ol><h2 id="_3-2-program-logic-analysis" tabindex="-1">3.2 Program Logic Analysis <a class="header-anchor" href="#_3-2-program-logic-analysis" aria-label="Permalink to &quot;3.2 Program Logic Analysis&quot;">​</a></h2><h3 id="_3-2-1-lesson-1-logical-of-traffic-light-program" tabindex="-1">3.2.1 <strong>Lesson 1 Logical of Traffic Light Program</strong> <a class="header-anchor" href="#_3-2-1-lesson-1-logical-of-traffic-light-program" aria-label="Permalink to &quot;3.2.1 **Lesson 1 Logical of Traffic Light Program**&quot;">​</a></h3><p>The screenshots used in this file are not the complete program. If want to view the detailed content , please go to this folder “<strong>Mini Autonomous Driving Kit/3.Program Download/Appendix</strong>”.</p><p>In this game, RGB module plays the role of traffic light. Let’s analyze how to set up a program to realize the cyclic and alternating flashing of red and green lights.</p><p>RGB module needs to keep flashing so the repeat executing statement will be used in here.</p><img loading="lazy" height="260" width="385" src="'+m+'" style="width:300px;" class="common_img"><ol><li>Then drag the program block of RGB module color setting and set the port to 8, and two RGB lights are red.</li></ol><img loading="lazy" height="296" width="760" src="'+h+'" style="width:500px;" class="common_img"><ol start="2"><li>Then set the duration time of red light.</li></ol><img loading="lazy" height="330" width="744" src="'+p+'" style="width:500px;" class="common_img"><ol start="3"><li>After setting red, then green. Likewise, add a delay. The duration can be set according to the actual situation.</li></ol><img loading="lazy" height="454" width="765" src="'+w+'" style="width:500px;" class="common_img"><ol start="4"><li>At this step, the entire traffic light program has been programmed.</li></ol><h3 id="_3-2-2-lesson-2-logical-of-autonomous-driving-program" tabindex="-1">3.2.2 Lesson 2 Logical of Autonomous Driving Program <a class="header-anchor" href="#_3-2-2-lesson-2-logical-of-autonomous-driving-program" aria-label="Permalink to &quot;3.2.2 Lesson 2 Logical of Autonomous Driving Program&quot;">​</a></h3><p>The screenshots used in this file are not the complete program. If want to view the detailed content, please go to this folder “<strong>Mini Autonomous Driving Kit/3.Program Download/Appendix</strong>”.</p><ol><li>Firstly, initialize each module.</li></ol><img loading="lazy" height="719" width="711" src="'+f+'" style="width:500px;" class="common_img"><ol start="2"><li>Then set whether to turn left or right after robot car recognizes the road sign. In order to make the program framework more intuitive and neat, the method of sub-threading is used here to program.</li></ol><img loading="lazy" height="439" width="447" src="'+b+'" style="width:500px;" class="common_img"><p>The specific program for detecting road sign is as follow:</p><img loading="lazy" height="776" width="790" src="'+u+'" style="width:800px;" class="common_img"><ol><li>Switch WonderCam vision module to Landmark recognition.</li></ol><img loading="lazy" height="230" width="572" src="'+D+'" style="width:500px;" class="common_img"><ol start="2"><li>Next, the following several functions are used to control robot car to follow line.</li></ol><img loading="lazy" height="266" width="576" src="'+Q+'" style="width:800px;" class="common_img"><ol start="3"><li>Updating line following sensor is mainly to update the detection values of the sensor’s four probes in real time, as the figure shown below:</li></ol><img loading="lazy" height="298" width="816" src="'+N+'" style="width:800px;" class="common_img"><ol start="4"><li>The function of the white line detection is to set the variable of white line detection to 1 if the white line is detected by four probes.</li></ol><img loading="lazy" height="234" width="1049" src="'+y+'" style="width:800px;" class="common_img"><ol start="5"><li>The general line following logic program can make the car move forward and turn according to the detection situation of the four probes.</li></ol><img loading="lazy" height="773" width="933" src="'+B+'" style="width:800px;" class="common_img"><ol start="6"><li>When WonderCam recognizes ID2 or ID3, that is, turning left or right, the robot car will stop and end the road sign recognition.</li></ol><img loading="lazy" height="295" width="769" src="'+R+'" style="width:800px;" class="common_img"><ol start="7"><li>When WonderCam recognizes the road sign card of ID2, that is, turn left, set the robot car to turn left, otherwise, turn right.</li></ol><img loading="lazy" height="516" width="518" src="'+v+'" style="width:500px;" class="common_img"><ol start="8"><li>Then, the robot car keeps moving. When four probes detect the white line, the traffic light detection starts.</li></ol><img loading="lazy" height="231" width="576" src="'+P+'" style="width:500px;" class="common_img"><ol start="9"><li>After the robot car recognizes the green light, it will broadcast the audio that allows passage once, and the broadcast cannot affect the traffic light detection, so set green to 1 and use a loop statement to make WonderCam detect repeatedly.</li></ol><img loading="lazy" height="864" width="637" src="'+x+'" style="width:500px;" class="common_img"><ol start="10"><li>Finally, through repetition execution statement, the entire recognition process is repeated to realize the effect that the car recognizes and moves continuously.</li></ol><img loading="lazy" height="523" width="526" src="'+U+'" style="width:500px;" class="common_img">',67)])])}const T=t(E,[["render",C]]);export{W as __pageData,T as default};
